using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class CorridorVerify {static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("B5_CorridorOnly_Guidance");var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_CorridorOnlyGuidance/plan.json"));var data=JObject.Parse(File.ReadAllText(Repo+"/Docs/검수/2026-11-08_B5_CorridorOnlyGuidance/apply.json"));int vertices=0,inside=0,wrongDomain=0,sourceStillVisible=0;float minRoomClearance=100;foreach(var f in group.GetComponentsInChildren<MeshFilter>()){string corridor=f.name.Split('_')[2];var box=data["boundaries"].Single(x=>(string)x["id"]=="B5-"+corridor);var a=new Vector2((float)box["a"][0],(float)box["a"][1]);var b=new Vector2((float)box["b"][0],(float)box["b"][1]);var fw=(b-a).normalized;var right=new Vector2(fw.y,-fw.x);foreach(var vv in f.sharedMesh.vertices){var v=f.transform.TransformPoint(vv);var p=new Vector2(v.x,v.z);vertices++;float z=Vector2.Dot(p-a,fw),x=Vector2.Dot(p-a,right);if(z<-.0001f||z>Vector2.Distance(a,b)+.0001f||Mathf.Abs(x)>(float)box["half"]+.0001f)wrongDomain++;foreach(var room in (JObject)plan["rooms"]){float gap=Vector2.Distance(p,new Vector2((float)room.Value["x"],-(float)room.Value["v"]))-(float)room.Value["r"];minRoomClearance=Mathf.Min(minRoomClearance,gap);if(gap<-.0001f)inside++;}}}foreach(var c in data["changes"]){string p=(string)c["path"];var t=root.Find(p.Substring(root.name.Length+1));if(!t||t.GetComponent<Renderer>().enabled)sourceStillVisible++;}var result=new{vertices,domeInteriorVertices=inside,outsideCorridorVertices=wrongDomain,minRoomClearance,sourceStillVisible,colliders=group.GetComponentsInChildren<Collider>().Length,monoBehaviours=group.GetComponentsInChildren<MonoBehaviour>().Length};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_CorridorOnlyGuidance/verification.json",JsonConvert.SerializeObject(result,Formatting.Indented));if(inside+wrongDomain+sourceStillVisible!=0)throw new Exception("Verification failed");return result;}}
